                (_, OneShotResourceValue::Empty) => a,
                (
                    OneShotResourceValue::HalfRightToComplete,
                    OneShotResourceValue::HalfRightToComplete,
                ) => OneShotResourceValue::FullRightToComplete {  },
                (
                    OneShotResourceValue::Complete,
                    OneShotResourceValue::Complete,
                ) => OneShotResourceValue::Complete {  },
                (_, _) => OneShotResourceValue::Invalid {  },
            }
        }

